data.transform:
(
  $L := $state.context.LOCAL;
  $f := $L.facility;
  $id := $string($L.trx[0].id);
  $fuuzId:= $coalesce( [$state.context.LOCAL.fztrx.id,$cuid()]);
  {
    "to": {
        "create": $L.trx[mainline='T'].(

          $ff := $string(location);
          $tf := $string(transferlocation);
          {
            "id": $fuuzId,
            "externalId": $id,
            "number": tranid,
            "priorityId": "Normal",
            "issuedAt": $moment(trandate),
            "dueAt":  $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "transferOrderTypeId": $f[externalId=$tf].type.outside?"Outside Processor":"Internal",
            "transferOrderStatusId": "Pending Fulfillment",
            "fromFacilityId": $f[externalId=$ff].id,
            "toFacilityId": $f[externalId=$tf].id,
            "integrationData": $
          }
        ),
        "update":$L.trx[mainline='T'].(

          $ff := $string(location);
          $tf := $string(transferlocation);
          {
            "externalId": $id,
            "number": tranid,
            "priorityId": "Normal",
            "issuedAt": $moment(trandate),
            "dueAt":  $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "transferOrderTypeId": $f[externalId=$tf].type.outside?"Outside Processor":"Internal",
            "transferOrderStatusId": "Pending Fulfillment",
            "fromFacilityId": $f[externalId=$ff].id,
            "toFacilityId": $f[externalId=$tf].id,
            "integrationData": $
          }
        ),
          "where":{"id":$fuuzId}
      },
      "tol": $L.trx[mainline = "F"].{
        "create": (
          $i:=$string(item);
          {
            "externalId": $string(uniquekey),
            "code": $string(tranid) & ":"
              & $string(linesequencenumber),
            "number": $string(linesequencenumber),
            "transferQuantity": {
              "value":0-quantity,
              "unitId": $string(units)
            },
            "shippedQuantity": {
              "value":0,
              "unitId": $string(units)
            },
            "receivedQuantity": {
              "value":0,
              "unitId": $string(units)
            },
            "productId": $L.product[externalId=$i].id,
            "productStrategyProcessId": $L.product[externalId=$i].strategies.edges.node.strategyProcesses.edges.node.id,
            "transferOrderLineStatusId": "New",
            "transferOrderId": $fuuzId,
            "expectedShipAt":  $isNilOrEmpty(expectedshipdate) ? ($isNilOrEmpty(shipdate) ? $moment() : $moment(shipdate)) : $moment(expectedshipdate),
            "expectedReceiptAt": $isNilOrEmpty(expectedreceiptdate) ? null : $moment(expectedreceiptdate),
            "integrationData": $
          }
        )
      }
    }
)

data.query:
query (
  $to: TransferOrderWhereInput
  $product: ProductWhereInput
  $unit: UnitWhereInput
  $facility: FacilityWhereInput
) {
  to: transferOrder(where: $to) {
    edges {
      node {
        id
        externalId
        transferOrderStatusId
        lines {
          edges {
            node {
              id
            }
          }
        }
        shipments {
          edges {
            node {
              id
            }
          }
        }
        receipts {
          edges {
            node {
              id
            }
          }
        }
      }
    }
  }
  product(where: $product) {
    edges {
      node {
        id
        externalId
        productTypeId
        strategies {
          edges {
            node {
              id
              strategyProcesses(where: { final: { _eq: true } }) {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  unit(where: $unit) {
    edges {
      node {
        id
      }
    }
  }
  facility(where: $facility) {
    edges {
      node {
        id
        externalId
        type{
          outside
        }
      }
    }
  }
}

query Query{
  status:transferOrderStatus{
    edges {
      node {
        id
        name
        externalId
      }
    }
  }
}

